        window.location.href = `mailto:?subject=${subject}&body=${body}`;

        alert("O PDF foi baixado automaticamente. Por favor, anexe-o ao e-mail que foi aberto.");
      }
    } catch (error) {
      console.error("Erro ao compartilhar:", error);
    }
  };

