        setTimeout(() => {
            alert("⬇️ O PDF foi baixado no seu computador.\n\nO WhatsApp Web foi aberto. Por favor, arraste o arquivo PDF baixado para a conversa.");
        }, 1000);
      }
    } catch (error) {
      console.error("Erro ao enviar para WhatsApp:", error);
    }
  };

