import { jsPDF } from 'jspdf';
import { ReceiptData } from '../types';
import QRCode from 'qrcode';
import JsBarcode from 'jsbarcode';

// Colors Palette
const COLORS = {
  brandBlue: '#1e40af',
  textDark: '#000000',
  textGray: '#333333',
  borderGray: '#000000', // DANFE uses black borders
  bgLight: '#ffffff',
  white: '#ffffff',
};

type DocType = 'RECIBO' | 'NOTA_FISCAL';

/**
 * Generates a random 44-digit numeric string for simulated Access Key
 */
const generateAccessKey = () => {
  let key = "";
  for (let i = 0; i < 44; i++) {
    key += Math.floor(Math.random() * 10).toString();
  }
  return key.replace(/(.{4})/g, '$1 ').trim();
};

export const createPDFDoc = async (data: ReceiptData, type: DocType = 'RECIBO'): Promise<jsPDF> => {
  const doc = new jsPDF();
  const margin = 10;
  const pageWidth = 210;
  const contentWidth = pageWidth - (margin * 2);
  const pageHeight = 297;
  let y = 10;

  if (type === 'NOTA_FISCAL') {
    // --- DANFE LAYOUT ---
    doc.setFont("helvetica", "normal");

    // 1. TOP BOX (Logo, DANFE info, Barcode)
    doc.setLineWidth(0.2);
    doc.rect(margin, y, contentWidth, 35); // Main header box

    // Logo / Emitter Section
    doc.setFont("helvetica", "bold");
    doc.setFontSize(14);
    doc.text("BELCONFORT CAMAS E MÓVEIS", margin + 2, y + 6);
    doc.setFontSize(7);
    doc.setFont("helvetica", "normal");
    doc.text("RUA B, 103C, CASTANHEIRA", margin + 2, y + 10);
    doc.text("BELEM - PA - CEP: 66645-000", margin + 2, y + 13);
    doc.text("FONE: (91) 99381-2592", margin + 2, y + 16);
    doc.text("belconfortcamasemoveis@gmail.com", margin + 2, y + 19);

    // DANFE Middle Title
    doc.line(margin + 75, y, margin + 75, y + 35);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(10);
    doc.text("DANFE", margin + 82, y + 7);
    doc.setFontSize(6);
    doc.setFont("helvetica", "normal");
    doc.text("Documento Auxiliar da", margin + 77, y + 11);
    doc.text("Nota Fiscal Eletrônica", margin + 77, y + 14);

    doc.setFontSize(7);
    doc.text("0 - ENTRADA", margin + 77, y + 20);
    doc.text("1 - SAÍDA", margin + 77, y + 23);
    doc.setFont("helvetica", "bold");
    doc.rect(margin + 93, y + 18, 5, 5);
    doc.text("1", margin + 94.5, y + 21.5);

    doc.setFontSize(8);
    const nfNumber = (Math.floor(Math.random() * 900000) + 100000).toString();
    doc.text(`Nº 000.${nfNumber.substring(0,3)}.${nfNumber.substring(3,6)}`, margin + 77, y + 28);
    doc.text("SÉRIE 001", margin + 77, y + 32);

    // Barcode / Access Key Section
    doc.line(margin + 105, y, margin + 105, y + 35);
    const accessKey = generateAccessKey();

    try {
      const canvas = document.createElement('canvas');
      JsBarcode(canvas, accessKey.replace(/\s/g, ''), { format: "CODE128", width: 1, height: 40, displayValue: false, margin: 0 });
      doc.addImage(canvas.toDataURL(), 'PNG', margin + 108, y + 2, 82, 12);
    } catch(e) {}

    doc.setFontSize(6);
    doc.setFont("helvetica", "bold");
    doc.text("CHAVE DE ACESSO", margin + 107, y + 18);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(7);
    doc.text(accessKey, margin + 107, y + 21);

    doc.line(margin + 105, y + 24, margin + pageWidth - 20, y + 24);
    doc.setFontSize(6);
    doc.setFont("helvetica", "bold");
    doc.text("CONSULTA DE AUTENTICIDADE NO PORTAL NACIONAL DA NF-E", margin + 107, y + 27);
    doc.setFont("helvetica", "normal");
    doc.text("www.nfe.fazenda.gov.br/portal ou no site da Sefaz Autorizadora", margin + 107, y + 30);

    y += 35;

    // 2. NATUREZA DA OPERAÇÃO / PROTOCOLO
