    doc.setFont("helvetica", "normal");
    doc.text(dateEmi, margin + 176.5, y + 7);

    y += 8;
    doc.line(margin, y, margin + 175, y);
    doc.setFontSize(6);
    doc.setFont("helvetica", "bold");
    doc.text("MUNICÍPIO", margin + 2, y + 3);
    doc.setFontSize(8);
    doc.setFont("helvetica", "normal");
    doc.text(data.city || "BELEM", margin + 2, y + 7);

    doc.line(margin + 85, y, margin + 85, y + 8);
    doc.setFontSize(6);
    doc.setFont("helvetica", "bold");
    doc.text("FONE / FAX", margin + 87, y + 3);
    doc.setFontSize(8);
    doc.setFont("helvetica", "normal");
    doc.text(data.contact1 || "-", margin + 87, y + 7);

    doc.line(margin + 120, y, margin + 120, y + 8);
    doc.setFontSize(6);
    doc.setFont("helvetica", "bold");
    doc.text("UF", margin + 122, y + 3);
    doc.setFontSize(8);
    doc.setFont("helvetica", "normal");
    doc.text("PA", margin + 122, y + 7);

    doc.line(margin + 135, y, margin + 135, y + 8);
    doc.setFontSize(6);
    doc.setFont("helvetica", "bold");
    doc.text("INSCRIÇÃO ESTADUAL", margin + 137, y + 3);
    doc.setFontSize(8);
    doc.setFont("helvetica", "normal");
    doc.text("ISENTO", margin + 137, y + 7);

    doc.setFontSize(5.5);
    doc.setFont("helvetica", "bold");
    doc.text("HORA DA SAÍDA", margin + 176.5, y + 3);
    doc.setFontSize(8);
    doc.setFont("helvetica", "normal");
    doc.text(new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }), margin + 176.5, y + 7);

    y += 12;

    // 5. CÁLCULO DO IMPOSTO
    doc.setFont("helvetica", "bold");
    doc.setFontSize(8);
    doc.text("CÁLCULO DO IMPOSTO", margin, y - 1);
    doc.rect(margin, y, contentWidth, 16);

    const impWidth = contentWidth / 5;
    const drawImpCell = (label: string, value: string, x: number, line: number) => {
      const top = y + (line * 8);
      doc.setFontSize(5);
      doc.setFont("helvetica", "bold");
      doc.text(label, x + 1, top + 3);
      doc.setFontSize(8);
      doc.setFont("helvetica", "normal");
      doc.text(value, x + impWidth - 1, top + 7, { align: "right" });
      if (x + impWidth < margin + contentWidth) {
        doc.line(x + impWidth, top, x + impWidth, top + 8);
      }
    };

    let subtotal = data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
    let manualDiscount = 0;
    if (data.discountType === 'fixed') manualDiscount = data.discountValue;
    else manualDiscount = subtotal * (data.discountValue / 100);
    const bundleDiscount = data.bundleDiscount || 0;
    const totalDiscount = manualDiscount + bundleDiscount;
    const totalValue = Math.max(0, subtotal - totalDiscount);

    drawImpCell("BASE DE CÁLC. DO ICMS", "0,00", margin, 0);
    drawImpCell("VALOR DO ICMS", "0,00", margin + impWidth, 0);
    drawImpCell("BASE CÁLC. ICMS ST", "0,00", margin + impWidth * 2, 0);
    drawImpCell("VALOR DO ICMS ST", "0,00", margin + impWidth * 3, 0);
    drawImpCell("VALOR TOTAL DOS PRODUTOS", subtotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 }), margin + impWidth * 4, 0);

    doc.line(margin, y + 8, margin + contentWidth, y + 8);

    drawImpCell("VALOR DO FRETE", "0,00", margin, 1);
    drawImpCell("VALOR DO SEGURO", "0,00", margin + impWidth, 1);
    drawImpCell("DESCONTO", totalDiscount.toLocaleString('pt-BR', { minimumFractionDigits: 2 }), margin + impWidth * 2, 1);
    drawImpCell("OUTRAS DESP. ACESS.", "0,00", margin + impWidth * 3, 1);
    drawImpCell("VALOR TOTAL DA NOTA", totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 }), margin + impWidth * 4, 1);

    y += 20;

    // 6. DADOS DO PRODUTO / SERVIÇO
    doc.setFont("helvetica", "bold");
    doc.setFontSize(8);
    doc.text("DADOS DO PRODUTO / SERVIÇO", margin, y - 1);

    const prodCols = [
      { name: "CÓDIGO", w: 15 },
      { name: "DESCRIÇÃO DO PRODUTO / SERVIÇO", w: 75 },
      { name: "NCM/SH", w: 15 },
      { name: "CST", w: 8 },
      { name: "CFOP", w: 10 },
      { name: "UN", w: 8 },
      { name: "QTD", w: 10 },
      { name: "V. UNIT", w: 16 },
      { name: "V. TOTAL", w: 16 },
      { name: "BC ICMS", w: 17 }
    ];

    doc.rect(margin, y, contentWidth, 5);
    let curX = margin;
    doc.setFontSize(5);
    prodCols.forEach(col => {
      doc.text(col.name, curX + 1, y + 3.5);
      curX += col.w;
      if (curX < margin + contentWidth) doc.line(curX, y, curX, y + 5);
    });

    y += 5;
    const itemsBoxHeight = 80;
    doc.rect(margin, y, contentWidth, itemsBoxHeight);

    let itemY = y + 4;
    doc.setFontSize(6);
    doc.setFont("helvetica", "normal");

    data.products.forEach(p => {
      if (itemY > y + itemsBoxHeight - 5) return;
      let colX = margin;
      doc.text(p.code?.substring(0, 8) || "001", colX + 1, itemY); colX += prodCols[0].w;
      doc.text(p.name.substring(0, 45).toUpperCase(), colX + 1, itemY); colX += prodCols[1].w;
      doc.text("94042100", colX + 1, itemY); colX += prodCols[2].w;
      doc.text("0400", colX + 1, itemY); colX += prodCols[3].w;
      doc.text("5102", colX + 1, itemY); colX += prodCols[4].w;
      doc.text("UN", colX + 1, itemY); colX += prodCols[5].w;
      doc.text(p.quantity.toString(), colX + 1, itemY); colX += prodCols[6].w;
      doc.text(p.price.toLocaleString('pt-BR', { minimumFractionDigits: 2 }), colX + prodCols[7].w - 1, itemY, { align: "right" }); colX += prodCols[7].w;
      doc.text((p.price * p.quantity).toLocaleString('pt-BR', { minimumFractionDigits: 2 }), colX + prodCols[8].w - 1, itemY, { align: "right" }); colX += prodCols[8].w;
      doc.text("0,00", colX + prodCols[9].w - 1, itemY, { align: "right" });
      itemY += 4;
    });

    y += itemsBoxHeight + 5;

    // 7. DADOS ADICIONAIS
    doc.setFont("helvetica", "bold");
    doc.setFontSize(8);
    doc.text("DADOS ADICIONAIS", margin, y - 1);
    doc.rect(margin, y, contentWidth, 30);

    doc.setFontSize(6);
    doc.text("INFORMAÇÕES COMPLEMENTARES", margin + 2, y + 4);
    doc.setFont("helvetica", "normal");
    const infoComp = [
      `Vendedor: ${data.salesperson}`,
      `Forma de Pagamento: ${data.paymentMethod}`,
      `Código da Venda: ${data.saleCode}`,
      "Empresa optante pelo Simples Nacional.",
      "Documento emitido por ME ou EPP optante pelo Simples Nacional.",
      "Não gera direito a crédito fiscal de IPI."
    ].join(" | ");

    // ADJUSTED WRAPPING: The box width for info is from margin+2 to 125 (start of reservado fisco)
    const infoWidth = 115; // margin is 10, 10+115 = 125
    const splitInfo = doc.splitTextToSize(infoComp, infoWidth);
    doc.text(splitInfo, margin + 2, y + 8);

    doc.line(margin + 125, y, margin + 125, y + 30); // Moved a bit right
    doc.setFont("helvetica", "bold");
    doc.text("RESERVADO AO FISCO", margin + 127, y + 4);

  } else {
    // --- LEGACY RECEIPT LAYOUT ---
    const headerHeight = 40;
    doc.setFillColor(COLORS.brandBlue);
    doc.rect(0, 0, pageWidth, headerHeight, 'F');
    doc.setTextColor(COLORS.white);
    doc.setFont("times", "bold");
    doc.setFontSize(26);
    doc.text("BelConfort", margin, 20);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(8);
    doc.text("CAMAS E MÓVEIS", margin, 26, { charSpace: 1.5 });

    const qrSize = 25;
    const qrX = pageWidth - margin - qrSize;
    const infoX = qrX - 5; 
    doc.setFont("helvetica", "bold");
    doc.setFontSize(9);
    doc.text("CNPJ 60.190.028/0001-60", infoX, 15, { align: "right" });
    doc.setFont("helvetica", "normal");
    doc.text("RUA B, 103C, CASTANHEIRA - BELEM/PA", infoX, 20, { align: "right" });
    doc.text("belconfortcamasemoveis@gmail.com", infoX, 25, { align: "right" });
    doc.text("(91) 99381-2592", infoX, 30, { align: "right" });

    try {
      const qrDataUrl = await QRCode.toDataURL('https://www.instagram.com/belconfortcamasemoveis/', {
          margin: 0,
          color: { dark: '#ffffff', light: '#1e40af' }
      });
      doc.addImage(qrDataUrl, 'PNG', qrX, 7, qrSize, qrSize);
    } catch (err) {}

    y = 48;
    doc.setTextColor(COLORS.textDark);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(14);
    doc.text("COMPROVANTE DE COMPRA", pageWidth / 2, y, { align: "center" });

    y += 5;
    doc.setFontSize(8);
    doc.setTextColor('#6b7280');
    doc.setFont("helvetica", "normal");
    const dateStr = new Date().toLocaleDateString('pt-BR');
    doc.text(`Emissão: ${dateStr}`, pageWidth / 2, y, { align: "center" });

    y += 10;
    // ...
  }

  return doc;
};

export const generateReceiptPDF = async (data: ReceiptData) => {
  const doc = await createPDFDoc(data, 'RECIBO');
  const safeName = data.name ? data.name.toUpperCase() : 'CLIENTE';
  doc.save(`COMPROVANTE - ${safeName}.pdf`);
};

export const generateInvoicePDF = async (data: ReceiptData) => {
  const doc = await createPDFDoc(data, 'NOTA_FISCAL');
  const safeName = data.name ? data.name.toUpperCase() : 'CLIENTE';
  doc.save(`NF - ${safeName}.pdf`);
};

export const getReceiptBlob = async (data: ReceiptData): Promise<Blob> => {
  const doc = await createPDFDoc(data, 'RECIBO');
  return doc.output('blob');
};

import { GoogleGenAI, Type } from "@google/genai";
import { ReceiptData } from "../types";

/**
 * Generates a friendly confirmation message for the client using Gemini.
 */
export const generateClientMessage = async (data: ReceiptData): Promise<string> => {
  // Use the pre-configured process.env.API_KEY directly as per coding guidelines
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

  const subtotal = data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  let discountAmount = 0;
  if (data.discountType === 'fixed') {
    discountAmount = data.discountValue;
  } else {
    discountAmount = subtotal * (data.discountValue / 100);
  }
  const finalTotal = Math.max(0, subtotal - discountAmount);

  const productsListText = data.products.length > 0 
    ? data.products.map(p => `- ${p.quantity}x ${p.name} (${(p.price * p.quantity).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })})`).join('\n')
    : "Não especificado";

  const totalText = finalTotal.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  const prompt = `
    Você é o motor de inteligência da BelConfort. Gere uma resposta extremamente profissional e cordial.

    DADOS DO PEDIDO:
    Cliente: ${data.name}
    Venda ID: ${data.saleCode}
    Valor Final: ${totalText}
    Lista de Itens:
    ${productsListText}

    MISSÃO:
    Escreva uma mensagem curta para WhatsApp. Seja direto, use emojis de forma sofisticada e agradeça a confiança na BelConfort.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: "Você é um assistente de elite da BelConfort. Seu tom é executivo, acolhedor e focado em eficiência. Evite redundâncias e saudações genéricas de IA."
      }
    });

    return response.text || "Não foi possível gerar a mensagem.";
  } catch (error: any) {
    console.error("Error generating message:", error);
    throw error;
  }
};

/**
 * Parses receipt text into structured JSON data using Gemini.
 */
export const parseReceiptFromText = async (text: string, catalogNames: string[] = []): Promise<any> => {
  // Use the pre-configured process.env.API_KEY directly as per coding guidelines
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

  const catalogString = catalogNames.join(", ");

  const prompt = `
    Analise a ficha técnica/texto de venda abaixo e extraia cada bit de informação com precisão absoluta.

    DIRETRIZES:
    1. Localize Nome, CPF/CNPJ e Endereço Completo.
    2. Mapeie cada produto para o nome correspondente no catálogo oficial: [${catalogString}]
    3. REGRAS DE BRINDES: Se o cliente "ganhou" ou tem travesseiro como "cortesia", mapeie para: "TRAVESSEIRO FLOCOS CONFORTO 20CM 60X40 BRANCO".
    4. DATA: Se não houver data, deixe vazio para preenchimento manual.

    TEXTO DO CLIENTE:
    ${text}
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        systemInstruction: "Você é um extrator de dados JSON de alta performance. Sua prioridade é a integridade dos dados e a correspondência exata de nomes de produtos do catálogo.",
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            clientData: {
              type: Type.OBJECT,
              properties: {
                saleCode: { type: Type.STRING },
                name: { type: Type.STRING },
                cpf: { type: Type.STRING },
                date: { type: Type.STRING },
                email: { type: Type.STRING },
                street: { type: Type.STRING },
                number: { type: Type.STRING },
                neighborhood: { type: Type.STRING },
                city: { type: Type.STRING },
                complement: { type: Type.STRING },
                contact1: { type: Type.STRING },
                contact2: { type: Type.STRING },
                paymentMethod: { type: Type.STRING },
              }
            },
            items: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  quantity: { type: Type.NUMBER }
                }
              },
            }
          }
        }
      }
    });

    const jsonText = response.text;
    if (!jsonText) throw new Error("Resposta vazia.");

    return JSON.parse(jsonText);
  } catch (error: any) {
    console.error("Error parsing receipt text:", error);
    throw error;
  }
};

